class Solution {
public:
    bool isStrictlyPalindromic(int n) {
        for (int b = 2; b <= n - 2; b++) {
            vector<int> d;
            for (int x = n; x; x /= b) d.push_back(x % b);
            if (!equal(d.begin(), d.end(), d.rbegin())) return false;
        }
        return true;
    }
};

