class Solution {
    public boolean isStrictlyPalindromic(int n) {
        for (int b = 2; b <= n - 2; b++) {
            List<Integer> d = new ArrayList<>();
            for (int x = n; x > 0; x /= b) d.add(x % b);
            for (int i = 0, j = d.size() - 1; i < j; i++, j--)
                if (!d.get(i).equals(d.get(j))) return false;
        }
        return true;
    }
}

