var isStrictlyPalindromic = function(n) {
    for (let b = 2; b <= n - 2; b++) {
        const d = [];
        for (let x = n; x > 0; x = Math.floor(x / b)) d.push(x % b);
        for (let i = 0, j = d.length - 1; i < j; i++, j--)
            if (d[i] !== d[j]) return false;
    }
    return true;
};

